const raw = $input.first().json;
const body = raw.body || raw;

// Hỗ trợ cả trigger từ Web / cURL và Slack Interactive Payload
let data = body;
if (body.payload) {
  try {
    data = typeof body.payload === 'string' ? JSON.parse(body.payload) : body.payload;
  } catch(e) {
    data = body;
  }
}

let quoteId = data.quote_id || data.id || '';
let action = (data.action || 'REQUEST_APPROVAL').toUpperCase();
let approver = data.approver || data.user?.name || data.user?.username || 'Sales Manager';
let note = data.note || data.approval_note || 'Xử lý qua cổng phê duyệt tự động';

if (data.actions && data.actions.length > 0) {
  try {
    const val = JSON.parse(data.actions[0].value);
    action = val.action || action;
    quoteId = val.quote_id || quoteId;
  } catch(e) {}
}

const isValid = Boolean(quoteId && typeof quoteId === 'string' && quoteId.trim().length > 0);

return [{
  json: {
    quote_id: quoteId.trim(),
    action: action,
    approver: approver,
    note: note,
    is_valid: isValid,
    received_at: new Date().toISOString()
  }
}];

const quote = $input.first().json;
const reqInput = $('Code (Normalize & Validate Input)').first().json;

let itemsList = quote.items;
if (typeof itemsList === 'string') {
  try { itemsList = JSON.parse(itemsList); } catch(e) { itemsList = []; }
}
if (!Array.isArray(itemsList)) itemsList = [];

const discount = Number(quote.discount_percent) || 0;
const totalAmount = Number(quote.total_amount) || 0;

let approvalLevel = 'STANDARD_MANAGER';
let requiresDirectorApproval = false;

if (discount >= 20 || totalAmount >= 50000000) {
  approvalLevel = 'SENIOR_DIRECTOR';
  requiresDirectorApproval = true;
}

let nextStatus = reqInput.action;
if (reqInput.action === 'REQUEST_APPROVAL') {
  nextStatus = 'PENDING_APPROVAL';
} else if (reqInput.action === 'APPROVE') {
  nextStatus = 'APPROVED';
} else if (reqInput.action === 'REJECT') {
  nextStatus = 'REJECTED';
}

return [{
  json: {
    ...quote,
    items_list: itemsList,
    action: nextStatus,
    approver: reqInput.approver,
    approval_note: reqInput.note,
    approval_level: approvalLevel,
    requires_director: requiresDirectorApproval,
    formatted_total: totalAmount.toLocaleString('vi-VN') + ' đ'
  }
}];

const item = $input.first().json;

const itemsSummary = item.items_list.map(i => 
  `• *${i.product || i.name}*: ${i.quantity} x ${Number(i.unit_price).toLocaleString('vi-VN')} đ`
).join('\n') || 'Không có chi tiết hạng mục';

const quoteShortId = item.id.slice(0, 8).toUpperCase();

const slackPayload = {
  text: `[WF-16] Cập nhật phê duyệt báo giá: #${quoteShortId} - Trạng thái: ${item.action}`,
  blocks: [
    {
      type: "header",
      text: {
        type: "plain_text",
        text: item.action === 'APPROVED' ? "✅ BÁO GIÁ ĐÃ ĐƯỢC PHÊ DUYỆT" :
              item.action === 'REJECTED' ? "❌ BÁO GIÁ ĐÃ BỊ TỪ CHỐI" : "🔔 YÊU CẦU DUYỆT BÁO GIÁ MỚI",
        emoji: true
      }
    },
    {
      type: "section",
      fields: [
        { type: "mrkdwn", text: `*Khách hàng:*\n${item.customer_name}` },
        { type: "mrkdwn", text: `*Công ty:*\n${item.company_name || 'N/A'}` },
        { type: "mrkdwn", text: `*Tổng tiền:*\n*${item.formatted_total}*` },
        { type: "mrkdwn", text: `*Chiết khấu:*\n${item.discount_percent}% (Cấp duyệt: ${item.approval_level})` }
      ]
    },
    {
      type: "section",
      text: {
        type: "mrkdwn",
        text: `*Danh mục sản phẩm:*\n${itemsSummary}`
      }
    },
    {
      type: "section",
      text: {
        type: "mrkdwn",
        text: `*Người thực hiện:* ${item.approver}\n*Ghi chú:* ${item.approval_note}`
      }
    }
  ]
};

return [{
  json: {
    ...item,
    slack_payload: slackPayload,
    quote_short_id: quoteShortId
  }
}];

const item = $input.first().json;

// Mô phỏng / Đóng gói kết quả gửi thông báo tới kênh Slack & Teams điều hành
const dispatchResult = {
  channel: '#sales-management-approvals',
  delivery_status: 'DELIVERED',
  event_type: item.action,
  dispatched_at: new Date().toISOString()
};

return [{
  json: {
    ...item,
    slack_dispatch_result: dispatchResult
  }
}];

const prev = $('Code (Slack Event Dispatcher Simulator)').first().json;
const updateRes = $input.first()?.json || {};

// Event Dispatcher: Kích hoạt các sự kiện tiếp theo tùy theo quyết định
let nextActionDescription = '';
if (prev.action === 'APPROVED') {
  nextActionDescription = 'Kích hoạt WF-14 gửi PDF báo giá chính thức cho khách hàng qua Email.';
} else if (prev.action === 'REJECTED') {
  nextActionDescription = 'Gửi thông báo trả về cho Sales Agent để điều chỉnh lại chiết khấu & số lượng.';
} else {
  nextActionDescription = 'Đã gửi thẻ duyệt tương tác lên kênh Slack chờ phê duyệt.';
}

const downstreamEvent = {
  event_name: `QUOTATION_${prev.action}`,
  quote_id: prev.id,
  target_customer: prev.customer_email,
  next_step: nextActionDescription,
  timestamp: new Date().toISOString()
};

return [{
  json: {
    success: true,
    message: `Đã cập nhật trạng thái báo giá #${prev.quote_short_id} thành ${prev.action}`,
    quote_id: prev.id,
    customer_name: prev.customer_name,
    total_amount: prev.total_amount,
    approval_status: prev.action,
    approved_by: prev.approver,
    approval_level: prev.approval_level,
    downstream_event: downstreamEvent,
    updated_at: updateRes.updated_at || new Date().toISOString()
  }
}];
